import { useEffect, useState } from 'react';
import { useParams, useOutletContext } from 'react-router-dom';
import useApi from '../hooks/useApi';
import { API_URLS } from '../services/api.urls';
import { Box, List, Checkbox } from '@mui/material';
import Email from './Email';
import { DeleteOutline } from '@mui/icons-material';
import NoMails from './common/NoMails';
import { EMPTY_TABS } from '../constants/constant';

const Emails = () => {
    const [starredEmail, setStarredEmail] = useState(false);
    const [selectedEmails, setSelectedEmails] = useState([]);
    const [loadError, setLoadError] = useState('');

    const { openDrawer } = useOutletContext();
    const { type } = useParams();

    const getEmailsService = useApi(API_URLS.getEmailFromType);
    const syncMailboxService = useApi(API_URLS.syncMailbox);
    const deleteEmailsService = useApi(API_URLS.deleteEmails);
    const moveEmailsToBin = useApi(API_URLS.moveEmailsToBin);

    const activeTab = EMPTY_TABS[type] ? type : 'inbox';

    useEffect(() => {
        const loadEmails = async () => {
            if (activeTab === 'allmail' || activeTab === 'inbox' || activeTab === 'starred' || activeTab === 'bin') {
                await syncMailboxService.call();
            }

            setLoadError('');
            await getEmailsService.call({}, activeTab);
            if (getEmailsService.error) {
                setLoadError(getEmailsService.error);
            }
        };

        loadEmails();
    }, [activeTab, starredEmail]);

    const selectAllEmails = (e) => {
        if (e.target.checked) {
            const emails = getEmailsService?.response?.map(email => email._id);
            setSelectedEmails(emails);
        } else {
            setSelectedEmails([]);
        }
    }

    const deleteSelectedEmails = () => {
        if (type === 'bin') {
            deleteEmailsService.call(selectedEmails);
        } else {
            moveEmailsToBin.call(selectedEmails);
        }
        setStarredEmail(prevState => !prevState);
    }

    return (
        <Box style={openDrawer ? { marginLeft: 250, width: '100%' } : { width: '100%' } }>
            <Box style={{ padding: '20px 10px 0 10px', display: 'flex', alignItems: 'center' }}>
                <Checkbox size="small" onChange={(e) => selectAllEmails(e)} />
                <DeleteOutline onClick={(e) => deleteSelectedEmails(e)} />
            </Box>
            <List>
                {
                    getEmailsService?.response?.map(email => (
                        <Email 
                            email={email} 
                            key={email._id || email.messageId}
                            setStarredEmail={setStarredEmail} 
                            selectedEmails={selectedEmails}
                            setSelectedEmails={setSelectedEmails}
                        />
                    ))
                }
            </List> 
            {
                loadError &&
                    <Box style={{ padding: 30 }}>
                        <NoMails message={{ heading: 'Could not load messages', subHeading: loadError }} />
                    </Box>
            }
            {
                !loadError && getEmailsService?.response?.length === 0 &&
                    <NoMails message={EMPTY_TABS[activeTab]} />
            }
        </Box>
    )
}

export default Emails;
